import{_ as t,o as h,c as i,a2 as c}from"./chunks/framework.mRCPFc5l.js";const m=JSON.parse('{"title":"Constructivism","description":"","frontmatter":{},"headers":[],"relativePath":"ideas/constructivism.md","filePath":"ideas/constructivism.md"}'),a={name:"ideas/constructivism.md"};function o(r,n,u,g,s,e){return h(),i("div",null,[...n[0]||(n[0]=[c('<h1 id="constructivism" tabindex="-1">Constructivism <a class="header-anchor" href="#constructivism" aria-label="Permalink to &quot;Constructivism&quot;">​</a></h1><p>Trên trang này# Constructivism <a href="#constructivism">​</a> Kiến thức không được chuyển từ thầy sang trò như rót nước. Mỗi learner <strong>tự dựng</strong> hiểu biết của mình bằng cách nối cái mới vào cái đã có sẵn trong đầu. Đây không phải một phương pháp dạy học — nó là một lý thuyết về việc học diễn ra thế nào. Nhiều phương pháp cụ thể (inquiry, project-based) đứng trên nền lý thuyết này.</p><h2 id="bai-toan-no-chi-ra-​" tabindex="-1">Bài toán nó chỉ ra <a href="#bai-toan-no-chi-ra">​</a> <a class="header-anchor" href="#bai-toan-no-chi-ra-​" aria-label="Permalink to &quot;Bài toán nó chỉ ra [​](#bai-toan-no-chi-ra)&quot;">​</a></h2><p>Nếu việc học đơn thuần là truyền thông tin, thì hai học sinh nghe cùng một bài giảng sẽ hiểu như nhau. Thực tế không bao giờ như vậy. Lý do: cái mới luôn được hiểu <strong>thông qua</strong> cái đã có. Một đứa trẻ đã biết chia đều bánh sẽ hiểu phân số khác hẳn một đứa trẻ chỉ biết phân số như &quot;số trên gạch số dưới&quot;. Cùng một bài giảng, hai kiến trúc trong đầu, hai kết quả.</p><h2 id="he-qua-thuc-te-​" tabindex="-1">Hệ quả thực tế <a href="#he-qua-thuc-te">​</a> <a class="header-anchor" href="#he-qua-thuc-te-​" aria-label="Permalink to &quot;Hệ quả thực tế [​](#he-qua-thuc-te)&quot;">​</a></h2><p><strong>Hiểu sai không phải lỗi ngẫu nhiên.</strong> Khi một học sinh tin rằng &quot;nhân thì luôn ra số lớn hơn&quot;, đó không phải sự cẩu thả — đó là một quy luật em ấy tự rút ra, hoàn toàn đúng với mọi ví dụ em từng gặp (số nguyên dương). Quy luật đó <strong>có logic</strong>, chỉ là phạm vi áp dụng bị hiểu quá rộng. Điều này đổi hẳn cách nên phản ứng. Nói &quot;sai rồi, nhân với 0.5 thì nhỏ đi&quot; thường không đủ — học sinh sẽ ghi nhớ như một ngoại lệ cần thuộc, còn quy luật cũ vẫn nguyên vẹn ở dưới. Cách hiệu quả hơn là <strong>tạo ra một tình huống mà quy luật cũ tự nó vỡ</strong>, rồi cùng xây lại. <strong>Kiến thức nền quyết định tốc độ học.</strong> Người biết nhiều về một lĩnh vực học thêm về lĩnh vực đó nhanh hơn hẳn — không phải vì họ thông minh hơn, mà vì họ có nhiều chỗ để móc cái mới vào. Đây cũng là lý do khoảng cách giữa học sinh có xu hướng doãng ra theo thời gian nếu không có can thiệp. <strong>Không nói ra thì không biết trong đầu learner đang có gì.</strong> Đây là lý do việc bắt learner giải thích lại có giá trị lớn: nó là cách duy nhất nhìn thấy cấu trúc đang có trong đầu con.</p><h2 id="nham-lan-pho-bien-nhat-​" tabindex="-1">Nhầm lẫn phổ biến nhất <a href="#nham-lan-pho-bien-nhat">​</a> <a class="header-anchor" href="#nham-lan-pho-bien-nhat-​" aria-label="Permalink to &quot;Nhầm lẫn phổ biến nhất [​](#nham-lan-pho-bien-nhat)&quot;">​</a></h2><p>Constructivism là lý thuyết về <strong>cách con người học</strong>. Nó <strong>không</strong> kéo theo kết luận rằng phải để trẻ tự khám phá mọi thứ. Từ &quot;tự dựng hiểu biết&quot; nhiều người nhảy sang &quot;vậy đừng dạy trực tiếp&quot;. Bước nhảy này không hợp lệ. Learner vẫn tự dựng hiểu biết của mình khi nghe một bài giảng rõ ràng — việc dựng diễn ra trong đầu họ, bất kể thông tin đến từ đâu. Bằng chứng thực tế khá rõ: với người mới bắt đầu, giảng dạy có cấu trúc thường hiệu quả hơn khám phá tự do. Điều đó không mâu thuẫn với constructivism.</p><h2 id="nemo12-dung-no-o-đau-​" tabindex="-1">Nemo12 dùng nó ở đâu <a href="#nemo12-dung-no-o-đau">​</a> <a class="header-anchor" href="#nemo12-dung-no-o-đau-​" aria-label="Permalink to &quot;Nemo12 dùng nó ở đâu [​](#nemo12-dung-no-o-đau)&quot;">​</a></h2><p><strong>Hỏi vì sao chọn đáp án đó.</strong> Sau khi trả lời, learner được hỏi đã làm cách nào: tự suy ra, nhớ lại, loại trừ, hay đoán. Câu trả lời này cho biết <em>cấu trúc trong đầu</em>, không chỉ kết quả — hai learner cùng chọn đúng có thể đang nghĩ theo hai cách hoàn toàn khác nhau. <strong>Sai được đọc như một quy luật, không như một lỗi.</strong> Khi một learner sai theo cùng một kiểu nhiều lần, đó là dấu hiệu của một quy luật sai đang hoạt động ổn định. Hệ thống nhắm vào quy luật đó, không nhắm vào việc sửa từng câu. <strong>Kiến thức được tổ chức thành mạng lưới, không thành danh sách.</strong> Mỗi mảng kiến thức biết mình cần những mảng nào làm nền. Đây chính là bản đồ &quot;chỗ để móc cái mới vào&quot;. <strong>Bắt giải thích lại.</strong> Các hoạt động phản tư yêu cầu learner nói ra hiểu biết của mình bằng lời — vừa là cách học, vừa là cách nhìn vào cấu trúc bên trong. Ở nhà Khi con làm sai, câu hỏi giá trị nhất không phải &quot;sai rồi, làm lại đi&quot; mà: <strong>&quot;con nghĩ thế nào mà ra kết quả này?&quot;</strong> Câu trả lời thường tiết lộ một quy luật hợp lý nhưng áp dụng sai chỗ. Sửa quy luật đó có tác dụng gấp nhiều lần sửa một bài toán. Bạn không đổ được kiến thức vào đầu ai. Bạn chỉ tạo được điều kiện để họ tự dựng nó — và điều kiện tốt nhất thường bao gồm cả việc dạy thật rõ ràng. <a href="/ideas/direct-instruction">Direct Instruction →</a></p>',10)])])}const d=t(a,[["render",o]]);export{m as __pageData,d as default};
